import { Component, inject } from '@angular/core';
import { Role } from 'app/features/access/role/model/role.model';
import { RoleRepository } from 'app/features/access/role/repository/role-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'role-view-delete-selection-action', standalone: false, template: '' })
export class RoleViewDeleteSelectionActionComponent extends ConfirmSelectionAction<Role> {
  readonly name = 'deleteSelection';
  protected readonly scope = 'access/role';
  protected readonly repository = inject(RoleRepository);

  protected runSelection(items: Role[]) {
    return this.repository.deleteSelection({ uids: items.map((item) => item.uid) });
  }
}
